-- Les ressources du personnage sont celles de resources, jamais des colonnes de fixture.
-- À rejouer APRES la dernière création des hôtes privés ; aucune activation de droit.
BEGIN;
DO $g$ DECLARE r record;v text;h text;n text;BEGIN
 FOR r IN SELECT DISTINCT colonne1 AS signature FROM (VALUES ('police_filature_commande(text,uuid)','b9fb18b681d2f59a9d0cadfb74da364c','b7dc6f5a932d6d8111cb3cec92596553'),('police_filature_commande(text,uuid)','646fca07f84d381130d96b52a24c0ed4','3cb0b1e6f4388228bdab325018a50e6f'),('police_enquete_commande(text,uuid)','a32c8051e8bed55afd755e85430a3989','8eab9cbf04270ca22b1cdc80f5db5b8d'),('police_chasse_commande(text,uuid)','1fa3b8fade0878bff0c6a482fd6506c4','4f074726f73b91a0ed4695fb31d529a7'),('vol_commande(text,text,uuid)','8567dfcbbd139898696f0547dda93682','0c67ee7c26e527a33d328a90354ce820')) t(colonne1,colonne2,colonne3) LOOP
  IF to_regprocedure('public.'||r.signature) IS NULL THEN CONTINUE;END IF;
  SELECT md5(prosrc),pg_get_functiondef(oid) INTO h,v FROM pg_proc WHERE oid=to_regprocedure('public.'||r.signature);
  IF NOT EXISTS(SELECT 1 FROM (VALUES ('police_filature_commande(text,uuid)','b9fb18b681d2f59a9d0cadfb74da364c','b7dc6f5a932d6d8111cb3cec92596553'),('police_filature_commande(text,uuid)','646fca07f84d381130d96b52a24c0ed4','3cb0b1e6f4388228bdab325018a50e6f'),('police_enquete_commande(text,uuid)','a32c8051e8bed55afd755e85430a3989','8eab9cbf04270ca22b1cdc80f5db5b8d'),('police_chasse_commande(text,uuid)','1fa3b8fade0878bff0c6a482fd6506c4','4f074726f73b91a0ed4695fb31d529a7'),('vol_commande(text,text,uuid)','8567dfcbbd139898696f0547dda93682','0c67ee7c26e527a33d328a90354ce820')) a(signature,ancien,nouveau) WHERE a.signature=r.signature AND h IN(a.ancien,a.nouveau)) THEN RAISE EXCEPTION 'definition_non_examinee: %',r.signature;END IF;
  n:=replace(replace(replace(replace(replace(replace(v,'coalesce(d.inf,0)','coalesce((d.resources->>''inf'')::numeric,0)'),'coalesce(p.inf,0)','coalesce((p.resources->>''inf'')::numeric,0)'),'coalesce(p.pop,0)','coalesce((p.resources->>''pop'')::integer,0)'),'SET pop=greatest(0,coalesce(pop,0)-10)','SET resources=jsonb_set(coalesce(resources,''{}''),''{pop}'',to_jsonb(greatest(0,coalesce((resources->>''pop'')::integer,0)-10)),true)'),'d.pop=greatest(0,','(d.resources->>''pop'')::integer=greatest(0,'),'''pop'',p.pop','''pop'',coalesce((p.resources->>''pop'')::integer,0)');
  EXECUTE n;
  SELECT md5(prosrc) INTO h FROM pg_proc WHERE oid=to_regprocedure('public.'||r.signature);
  IF NOT EXISTS(SELECT 1 FROM (VALUES ('police_filature_commande(text,uuid)','b9fb18b681d2f59a9d0cadfb74da364c','b7dc6f5a932d6d8111cb3cec92596553'),('police_filature_commande(text,uuid)','646fca07f84d381130d96b52a24c0ed4','3cb0b1e6f4388228bdab325018a50e6f'),('police_enquete_commande(text,uuid)','a32c8051e8bed55afd755e85430a3989','8eab9cbf04270ca22b1cdc80f5db5b8d'),('police_chasse_commande(text,uuid)','1fa3b8fade0878bff0c6a482fd6506c4','4f074726f73b91a0ed4695fb31d529a7'),('vol_commande(text,text,uuid)','8567dfcbbd139898696f0547dda93682','0c67ee7c26e527a33d328a90354ce820')) a(signature,ancien,nouveau) WHERE a.signature=r.signature AND h=a.nouveau) THEN RAISE EXCEPTION 'patch_resources_non_confirme: %',r.signature;END IF;
 END LOOP;
END;$g$;
COMMIT;
